def is_near(distance_m: float) -> bool:
    # 参数distance_m是本次调用的局部名字。
    if distance_m < 0:
        return False         # 条件命中立刻结束，后面语句不执行。
    return distance_m <= 35.0

def describe(distance_m: float) -> str:
    near = is_near(distance_m)  # 在一个函数里调用另一个函数。
    if near:
        return "距离提示"
    return "正常距离"

message = describe(34.0)        # 调用describe，得到返回的字符串。
print(message)
print(is_near(42.0))

def format_signal(value: float, unit: str = "km/h") -> str:
    return f"{value:.1f} {unit}"

print(format_signal(72.0))
print(format_signal(value=34.0, unit="m"))

def summarize(*values: float) -> tuple[float, int]:
    total = sum(values)  # values是tuple，不是普通单个float。
    return total, len(values)

total, count = summarize(1.0, 2.0, 3.0)
print(total, count)

def capture(**fields):
    return fields         # fields是dict。
print(capture(speed=72, valid=True))

